import torch, torch.nn as nn

class MoELayer(nn.Module):
    def __init__(self, d=512, n_experts=8, top_k=2):
        super().__init__()
        self.experts = nn.ModuleList([
            nn.Sequential(nn.Linear(d, d*4), nn.GELU(),
                          nn.Linear(d*4, d))       # 专家=FFN
            for _ in range(n_experts)])
        self.router = nn.Linear(d, n_experts)      # 分诊台
        self.top_k = top_k

    def forward(self, x):                      # x: (seq, d)
        scores = self.router(x)                # 每个 token 对 8 个专家打分
        topv, topi = scores.topk(self.top_k)   # 只选 2 个专家
        out = torch.zeros_like(x)
        for i in range(self.top_k):
            idx, expert_ids = topi[:, i], topi[:, i]
            for e in range(len(self.experts)):
                mask = expert_ids == e
                out[mask] += self.experts[e](x[mask]) * topv[mask, i:i+1]
        return out   # 只算了 top_k 个专家: 计算量≈2/8, 容量=全部专家

-- 三种防超卖写法对比（以 PG/MySQL 通用语义为例）
-- ① 原子条件更新（首选：无锁、一行搞定）
UPDATE inventory SET stock = stock - 1
 WHERE product_id = 42 AND stock > 0;
-- 检查受影响行数: 0 = 已售罄

-- ② 悲观锁：先锁行再操作
BEGIN;
SELECT stock FROM inventory WHERE product_id = 42 FOR UPDATE;
-- ...业务判断 + 下单落库...
UPDATE inventory SET stock = stock - 1 WHERE product_id = 42;
COMMIT;

-- ③ 乐观锁：读时不锁, 写时校验版本
UPDATE inventory SET stock = stock - 1, version = version + 1
 WHERE product_id = 42 AND version = 7;
-- 受影响行数 0 = 有人抢先了 -> 读最新版重试

